TEST = r"""import { expect, mock, test } from 'claude-code/testing'

test('a refused or rejected notify leaves the next refresh and notify working', async ($, on) => {
  const clock = mock.clock(on)
  let needs = 'nothing'
  let reject = true
  const notified: string[] = []
  const toasted: string[] = []
  const run = (stdout: string) => ({ value: { exitCode: 0, stdout, stderr: '' } })
  on('process.run', ($, e) => {
    const argv = e.argv as string[]
    if (argv.includes('--receipt')) {
      return run(JSON.stringify({ line: 'kbmon: no alert on querylog; needs you: 0', fingerprint: 'f1' }))
    }
    if (argv.includes('--status')) {
      return run(`needs you: ${needs}\nsessions: none\n`)
    }
    return run(`kbmon · 2026-10-24 10:00\nneeds you: ${needs}\n\nkb: 1 root\n`)
  })
  on('ui.notify', ($, e) => {
    notified.push(e.text)
    if (reject) {
      return { deny: 'another mod refused it' }
    }

    return { value: { isSent: false, reason: 'no-surface' } }
  })
  on('ui.toast', ($, e) => {
    toasted.push(e.text)

    return { value: undefined }
  })
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('command.register', () => ({ value: undefined }))
  on('session.start', () => ({ cwd: '/work' }))

  await $.session.start({ surface: 'terminal', isInteractive: true, cwd: '/work' })
  await clock.advance(2000)
  await clock.settle()

  needs = 'SP-aaaaaaaa gate start'
  await clock.advance(60000)
  await clock.settle()
  // the call rejected (denied by another mod): it was tried once and the refresh went on
  expect(notified.length).toBe(1)

  reject = false
  needs = 'SP-aaaaaaaa gate start; ask A0000000001 since 2026-10-24 14:02: which strategy'
  await clock.advance(60000)
  await clock.settle()
  // the next change is notified although the last call failed, and an answer of isSent false is no error
  expect(notified.length).toBe(2)

  needs = 'SP-bbbbbbbb gate review'
  await clock.advance(60000)
  await clock.settle()
  expect(notified.length).toBe(3)
})
"""
open(os.path.join(mod, 'planted.test.ts'), 'w', encoding='utf-8').write(TEST)
